// cacheBaselineFile pins conversion output produced by v0.1.4 for requests
// whose behaviour must not change when Chat cache_control parsing, the
// Anthropic breakpoint cap and AutoCache (off by default) were introduced.
//
// The golden file was generated by running this exact test against the v0.1.4
// tag with -update.cachebaseline; it must never be regenerated from a newer
// tree (doing so would turn the comparison into a tautology).
const cacheBaselineFile = "cache-baseline-v0.1.4.json"

var updateCacheBaseline = flag.Bool("update.cachebaseline", false, "regenerate the v0.1.4 cache baseline (run only on the v0.1.4 tag)")

type cacheBaselineCase struct {
	Name     string `json:"name"`
	From     string `json:"from"`
	To       string `json:"to"`
	Options  string `json:"options"`
	Body     string `json:"body,omitempty"`
	Error    string `json:"error,omitempty"`
	Losses   string `json:"losses,omitempty"`
	HasCache bool   `json:"has_cache,omitempty"`
}

// cacheBaselineRequests returns client requests keyed by name. Requests whose
// name starts with "marked-" carry Anthropic cache_control markers (at most
// four, none inside a single-text tool_result); every other request carries
// no cache marker at all.
func cacheBaselineRequests(t *testing.T) map[string]struct {
	from ir.Format
	body string
} {
	t.Helper()
	out := map[string]struct {
		from ir.Format
		body string
	}{}
	add := func(name string, from ir.Format, body string) {
		if _, dup := out[name]; dup {
			t.Fatalf("duplicate baseline request %q", name)
		}
		out[name] = struct {
			from ir.Format
			body string
		}{from, body}
	}
	fixtures := map[string]ir.Format{
		"chat.json":               ir.FormatChat,
		"chat-group.json":         ir.FormatChat,
		"anthropic.json":          ir.FormatAnthropic,
		"anthropic-group.json":    ir.FormatAnthropic,
		"anthropic-image.json":    ir.FormatAnthropic,
		"anthropic-thinking.json": ir.FormatAnthropic,
		"responses.json":          ir.FormatResponses,
		"responses-string.json":   ir.FormatResponses,
	}
	for file, from := range fixtures {
		b, err := os.ReadFile(filepath.Join(testdataDir, file))
		if err != nil {
			t.Fatalf("read fixture %s: %v", file, err)
		}
		add("fixture-"+strings.TrimSuffix(file, ".json"), from, string(b))
	}

	// Chat Completions requests without any cache marker.
	add("chat-simple", ir.FormatChat, `{"model":"m","messages":[{"role":"user","content":"hi"}]}`)
	add("chat-system-string", ir.FormatChat, `{"model":"m","messages":[{"role":"system","content":"You are terse."},{"role":"user","content":"hi"}],"max_tokens":256,"temperature":0.3}`)
	add("chat-system-parts", ir.FormatChat, `{"model":"m","messages":[{"role":"system","content":[{"type":"text","text":"Part A"},{"type":"text","text":"Part B"}]},{"role":"developer","content":"Dev note"},{"role":"user","content":[{"type":"text","text":"hello"}]}]}`)
	add("chat-image-file", ir.FormatChat, `{"model":"m","messages":[{"role":"user","content":[{"type":"text","text":"see"},{"type":"image_url","image_url":{"url":"https://example.com/a.png"}},{"type":"file","file":{"filename":"a.pdf","file_data":"data:application/pdf;base64,JVBERi0="}}]}]}`)
	add("chat-agent-loop", ir.FormatChat, `{"model":"m","stream":true,"messages":[{"role":"system","content":"sys"},{"role":"user","content":"list files"},{"role":"assistant","content":"Checking.","tool_calls":[{"id":"call_a","type":"function","function":{"name":"ls","arguments":"{\"dir\":\".\"}"}},{"id":"call_b","type":"function","function":{"name":"cat","arguments":"{\"path\":\"x\"}"}}]},{"role":"tool","tool_call_id":"call_a","content":"a.txt\nb.txt"},{"role":"tool","tool_call_id":"call_b","content":[{"type":"text","text":"line1"},{"type":"text","text":"line2"}]},{"role":"assistant","content":"Done."},{"role":"user","content":"thanks"}],"tools":[{"type":"function","function":{"name":"ls","description":"List","parameters":{"type":"object","properties":{"dir":{"type":"string"}}}}},{"type":"function","function":{"name":"cat","description":"Cat","strict":true,"parameters":{"type":"object","properties":{"path":{"type":"string"}},"required":["path"],"additionalProperties":false}}}],"tool_choice":"auto","parallel_tool_calls":false}`)
	add("chat-tool-single-text-part", ir.FormatChat, `{"model":"m","messages":[{"role":"user","content":"q"},{"role":"assistant","content":null,"tool_calls":[{"id":"call_1","type":"function","function":{"name":"f","arguments":"{}"}}]},{"role":"tool","tool_call_id":"call_1","content":[{"type":"text","text":"only"}]},{"role":"tool","tool_call_id":"call_1","content":""}],"tools":[{"type":"function","function":{"name":"f","parameters":{"type":"object"}}}],"tool_choice":{"type":"function","function":{"name":"f"}}}`)
	add("chat-mid-system", ir.FormatChat, `{"model":"m","messages":[{"role":"system","content":"top"},{"role":"user","content":"u1"},{"role":"assistant","content":"a1"},{"role":"system","content":"mid note"},{"role":"user","content":"u2"}],"stop":["END"],"user":"u-1","metadata":{"k":"v"}}`)
	add("chat-reasoning", ir.FormatChat, `{"model":"m","reasoning_effort":"high","messages":[{"role":"user","content":"u1"},{"role":"assistant","content":"a1","reasoning_content":"thought"},{"role":"user","content":"u2"}],"max_completion_tokens":20000}`)
	add("chat-response-format", ir.FormatChat, `{"model":"m","messages":[{"role":"user","content":"json please"}],"response_format":{"type":"json_schema","json_schema":{"name":"x","schema":{"type":"object","properties":{"a":{"type":"string"}}}}},"top_p":0.5,"seed":7,"n":1}`)
	add("chat-assistant-last", ir.FormatChat, `{"model":"m","messages":[{"role":"user","content":"start"},{"role":"assistant","content":[{"type":"text","text":"prefill"}]}]}`)

	// Responses / Gemini requests without any cache marker.
	add("responses-tools", ir.FormatResponses, `{"model":"m","instructions":"inst","input":[{"role":"user","content":[{"type":"input_text","text":"hi"}]},{"type":"function_call","call_id":"c1","name":"f","arguments":"{}"},{"type":"function_call_output","call_id":"c1","output":"ok"}],"tools":[{"type":"function","name":"f","parameters":{"type":"object"}}]}`)
	add("gemini-simple", ir.FormatGemini, `{"systemInstruction":{"parts":[{"text":"sys"}]},"contents":[{"role":"user","parts":[{"text":"hi"}]},{"role":"model","parts":[{"text":"hello"}]},{"role":"user","parts":[{"text":"again"}]}]}`)

	// Anthropic requests without markers.
	add("anthropic-tools-loop", ir.FormatAnthropic, `{"model":"m","max_tokens":512,"system":"sys","messages":[{"role":"user","content":"q"},{"role":"assistant","content":[{"type":"text","text":"calling"},{"type":"tool_use","id":"toolu_1","name":"f","input":{"a":1}}]},{"role":"user","content":[{"type":"tool_result","tool_use_id":"toolu_1","content":[{"type":"text","text":"r1"},{"type":"text","text":"r2"}]},{"type":"text","text":"next"}]}],"tools":[{"name":"f","description":"F","input_schema":{"type":"object"}}]}`)

	// Anthropic requests carrying at most four markers (v0.1.4 forwarded them as-is).
	add("marked-anthropic-system-tools", ir.FormatAnthropic, `{"model":"m","max_tokens":512,"system":[{"type":"text","text":"S1"},{"type":"text","text":"S2","cache_control":{"type":"ephemeral"}}],"tools":[{"name":"a","input_schema":{"type":"object"}},{"name":"b","input_schema":{"type":"object"},"cache_control":{"type":"ephemeral","ttl":"1h"}}],"messages":[{"role":"user","content":[{"type":"text","text":"hello","cache_control":{"type":"ephemeral"}}]}]}`)
	add("marked-anthropic-image-doc", ir.FormatAnthropic, `{"model":"m","max_tokens":512,"messages":[{"role":"user","content":[{"type":"image","source":{"type":"url","url":"https://example.com/a.png"},"cache_control":{"type":"ephemeral"}},{"type":"document","source":{"type":"text","media_type":"text/plain","data":"doc body"},"title":"T","cache_control":{"type":"ephemeral"}},{"type":"text","text":"what?"}]}]}`)
	add("marked-anthropic-tool-result-multi", ir.FormatAnthropic, `{"model":"m","max_tokens":512,"messages":[{"role":"user","content":"q"},{"role":"assistant","content":[{"type":"tool_use","id":"toolu_1","name":"f","input":{}}]},{"role":"user","content":[{"type":"tool_result","tool_use_id":"toolu_1","content":[{"type":"text","text":"r1"},{"type":"text","text":"r2","cache_control":{"type":"ephemeral"}}]}]}],"tools":[{"name":"f","input_schema":{"type":"object"}}]}`)
	return out
}

func cacheBaselineOptions() map[string]bridge.Options {
	base := func() bridge.Options { return bridge.Options{Allow: ir.DefaultAllowed} }
	gw := base()
	gw.OmitUserID = true
	gw.OmitHistoryReasoning = true
	gw.TrimLeadingNewlines = true
	gw.Anthropic = anthropic.Dialect{MidSystem: "fold", DisableWebSearch: true}
	gw.Chat = chat.Dialect{MidSystem: "fold", DisableWebSearch: true}
	return map[string]bridge.Options{"default": base(), "gateway": gw}
}

func lossSummary(ls []ir.Loss) string {
	parts := make([]string, 0, len(ls))
	for _, l := range ls {
		parts = append(parts, string(l.Kind)+"@"+l.Path.String())
	}
	return strings.Join(parts, ";")
}

func runCacheBaseline(t *testing.T) []cacheBaselineCase {
	reqs := cacheBaselineRequests(t)
	names := make([]string, 0, len(reqs))
	for n := range reqs {
		names = append(names, n)
	}
	sort.Strings(names)
	optSets := cacheBaselineOptions()
	optNames := []string{"default", "gateway"}
	targets := []ir.Format{ir.FormatAnthropic, ir.FormatChat, ir.FormatResponses, ir.FormatGemini}
	var cases []cacheBaselineCase
	for _, n := range names {
		r := reqs[n]
		for _, to := range targets {
			for _, on := range optNames {
				c := cacheBaselineCase{Name: n, From: string(r.from), To: string(to), Options: on, HasCache: strings.HasPrefix(n, "marked-")}
				plan, err := bridge.Convert(r.from, to, []byte(r.body), optSets[on])
				if err != nil {
					c.Error = err.Error()
				} else {
					c.Body = string(plan.Body)
					c.Losses = lossSummary(plan.Losses)
				}
				cases = append(cases, c)
			}
		}
	}
	return cases
}

// TestCacheBaseline_ByteExactV014 pins request conversion output against
// v0.1.4 for every request that carries no cache marker (body, error and
// recorded losses), and for Anthropic requests carrying at most four markers
// (body and error; losses may now additionally report dropped markers for
// formats that cannot express them).
func TestCacheBaseline_ByteExactV014(t *testing.T) {
	got := runCacheBaseline(t)
	path := filepath.Join(testdataDir, cacheBaselineFile)
	if *updateCacheBaseline {
		b, err := json.MarshalIndent(got, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, append(b, '\n'), 0o644); err != nil {
			t.Fatal(err)
		}
		t.Logf("wrote %d baseline cases", len(got))
		return
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read baseline: %v", err)
	}
	var want []cacheBaselineCase
	if err := json.Unmarshal(raw, &want); err != nil {
		t.Fatalf("decode baseline: %v", err)
	}
	if len(want) != len(got) {
		t.Fatalf("baseline has %d cases, current corpus has %d", len(want), len(got))
	}
	for i := range want {
		w, g := want[i], got[i]
		label := w.Name + " " + w.From + "->" + w.To + " [" + w.Options + "]"
		if w.Name != g.Name || w.From != g.From || w.To != g.To || w.Options != g.Options {
			t.Fatalf("case %d mismatch: baseline %s, current %s %s->%s [%s]", i, label, g.Name, g.From, g.To, g.Options)
		}
		if g.Body != w.Body {
			t.Errorf("%s: body diverged from v0.1.4\n got: %s\nwant: %s", label, g.Body, w.Body)
		}
		if g.Error != w.Error {
			t.Errorf("%s: error diverged from v0.1.4\n got: %s\nwant: %s", label, g.Error, w.Error)
		}
		if !w.HasCache && g.Losses != w.Losses {
			t.Errorf("%s: losses diverged from v0.1.4\n got: %s\nwant: %s", label, g.Losses, w.Losses)
		}
	}
}
